import React, { useEffect, useState, useCallback } from 'react';
import clientService from '../../services/clientService';
import PageHeader from '../../components/common/PageHeader';
import DataTable from '../../components/common/DataTable';
import Modal from '../../components/common/Modal';
import '../../components/common/shared.css';

const EMPTY_FORM = { name: '', email: '', phone: '', address: '' };

const ClientForm = ({ initial = EMPTY_FORM, onSubmit, onClose, loading, serverError }) => {
  const [form, setForm] = useState(initial);
  const [errors, setErrors] = useState({});

  const validate = () => {
    const e = {};
    if (!form.name.trim())  e.name  = 'Nom requis';
    if (!form.email.trim()) e.email = 'Email requis';
    else if (!/\S+@\S+\.\S+/.test(form.email)) e.email = 'Email invalide';
    return e;
  };

  const handle = ({ target: { name, value } }) => {
    setForm(p => ({ ...p, [name]: value }));
    if (errors[name]) setErrors(p => ({ ...p, [name]: '' }));
  };

  const submit = (e) => {
    e.preventDefault();
    const e2 = validate();
    if (Object.keys(e2).length) { setErrors(e2); return; }
    onSubmit(form);
  };

  return (
    <form onSubmit={submit}>
      {/* ✅ FIX : affichage de l'erreur serveur dans le formulaire, pas en alert() */}
      {serverError && (
        <div className="booking-error" style={{ marginBottom: '1rem' }}>
          {serverError}
        </div>
      )}
      <div className="form-grid">
        <div className="form-group">
          <label className="form-label">Nom *</label>
          <input name="name" className="form-input" value={form.name} onChange={handle} />
          {errors.name && <span className="form-error">{errors.name}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Email *</label>
          <input name="email" type="email" className="form-input" value={form.email} onChange={handle} />
          {errors.email && <span className="form-error">{errors.email}</span>}
        </div>
        <div className="form-group">
          <label className="form-label">Téléphone</label>
          <input name="phone" type="tel" className="form-input" value={form.phone} onChange={handle} />
        </div>
        <div className="form-group">
          <label className="form-label">Adresse</label>
          <input name="address" className="form-input" value={form.address} onChange={handle} />
        </div>
      </div>
      <div className="form-actions">
        <button type="button" className="btn btn--outline" onClick={onClose}>Annuler</button>
        <button type="submit" className="btn btn--primary" disabled={loading}>
          {loading ? <span className="dt-spinner" /> : 'Enregistrer'}
        </button>
      </div>
    </form>
  );
};

const ClientsPage = () => {
  const [clients, setClients]       = useState([]);
  const [loading, setLoading]       = useState(true);
  const [modal, setModal]           = useState(null);
  const [saving, setSaving]         = useState(false);
  const [search, setSearch]         = useState('');
  // ✅ FIX : état pour l'erreur serveur à afficher dans le modal
  const [serverError, setServerError] = useState('');

  const load = useCallback(() => {
    setLoading(true);
    clientService.getAll()
      .then(setClients)
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  // ✅ FIX : extraction du message d'erreur backend (409 email existant, 500, etc.)
  const extractError = (err) => {
    return (
      err?.response?.data?.message ||
      err?.response?.data?.error   ||
      err?.message                 ||
      'Une erreur est survenue'
    );
  };

  const handleCreate = async (form) => {
    setSaving(true);
    setServerError('');
    try {
      await clientService.create(form);
      setModal(null);
      load();
    } catch (err) {
      // ✅ FIX : affiche l'erreur dans le modal, pas en alert()
      setServerError(extractError(err));
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = async (form) => {
    setSaving(true);
    setServerError('');
    try {
      await clientService.update(modal.client.id, form);
      setModal(null);
      load();
    } catch (err) {
      setServerError(extractError(err));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Supprimer ce client ?')) return;
    try {
      await clientService.delete(id);
      load();
    } catch (err) {
      // Pour la suppression, on garde une alerte simple (modal fermé)
      alert(extractError(err));
    }
  };

  // ✅ FIX : réinitialiser l'erreur serveur à chaque ouverture de modal
  const openCreate = () => {
    setServerError('');
    setModal('create');
  };

  const openEdit = (client) => {
    setServerError('');
    setModal({ type: 'edit', client });
  };

  const filtered = clients.filter(c =>
    !search || c.name?.toLowerCase().includes(search.toLowerCase()) ||
    c.email?.toLowerCase().includes(search.toLowerCase())
  );

  const columns = [
    { key: 'name',    label: 'Nom' },
    { key: 'email',   label: 'Email' },
    { key: 'phone',   label: 'Téléphone' },
    { key: 'address', label: 'Adresse' },
  ];

  return (
    <div>
      <PageHeader
        title="Gestion des clients"
        subtitle={`${clients.length} client${clients.length > 1 ? 's' : ''} enregistrés`}
        action={
          <button className="btn btn--primary" onClick={openCreate}>
            + Ajouter client
          </button>
        }
      />

      <div style={{ marginBottom: '1rem' }}>
        <input
          type="text"
          className="form-input"
          placeholder="Rechercher par nom ou email…"
          value={search}
          onChange={e => setSearch(e.target.value)}
          style={{ maxWidth: 340 }}
        />
      </div>

      <DataTable
        columns={columns}
        data={filtered}
        loading={loading}
        empty="Aucun client trouvé."
        actions={row => (
          <div style={{ display: 'flex', gap: 6 }}>
            <button
              className="btn btn--sm btn--outline"
              onClick={() => openEdit(row)}
            >
              Modifier
            </button>
            <button
              className="btn btn--sm btn--danger"
              onClick={() => handleDelete(row.id)}
            >
              Supprimer
            </button>
          </div>
        )}
      />

      {modal === 'create' && (
        <Modal title="Ajouter un client" onClose={() => setModal(null)}>
          <ClientForm
            onSubmit={handleCreate}
            onClose={() => setModal(null)}
            loading={saving}
            serverError={serverError}
          />
        </Modal>
      )}

      {modal?.type === 'edit' && (
        <Modal title="Modifier le client" onClose={() => setModal(null)}>
          <ClientForm
            initial={modal.client}
            onSubmit={handleEdit}
            onClose={() => setModal(null)}
            loading={saving}
            serverError={serverError}
          />
        </Modal>
      )}
    </div>
  );
};

export default ClientsPage;
